package is.flati.bosstracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.OptionalInt;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class AgilityCourses
{
	static final String GRACE_LAPS_HEADER = "Agility Course Lap Counts";

	static final Pattern GRACE_LAP_ENTRY = Pattern.compile(
		"(?<course>.+?): (?<laps>\\d+) Laps?", Pattern.CASE_INSENSITIVE);

	static final Pattern GRACE_LAP_ENTRY_DASH = Pattern.compile(
		"(?<course>.+?)\\s*-\\s*(?<laps>\\d+) Laps?", Pattern.CASE_INSENSITIVE);

	private static final Pattern GRACE_LAP_LINE_DASH = Pattern.compile(
		"^(?<course>.+?)\\s*-\\s*(?<laps>\\d+) Laps?$", Pattern.CASE_INSENSITIVE);

	private static final Set<String> KNOWN_COURSES;
	private static final Map<String, String> ALIASES;
	private static final Map<String, String> GRACE_ROOFTOP_NAMES;
	private static final Set<String> GRACE_HEADER_SKIP;

	static
	{
		Set<String> courses = new HashSet<>();
		courses.add("Draynor Village Rooftop");
		courses.add("Al Kharid Rooftop");
		courses.add("Varrock Rooftop");
		courses.add("Canifis Rooftop");
		courses.add("Falador Rooftop");
		courses.add("Seers' Village Rooftop");
		courses.add("Pollnivneach Rooftop");
		courses.add("Rellekka Rooftop");
		courses.add("Ardougne Rooftop");
		courses.add("Gnome Stronghold");
		courses.add("Barbarian Outpost");
		courses.add("Wilderness Agility Course");
		courses.add("Ape Atoll");
		courses.add("Werewolf Agility Course");
		courses.add("Dorgesh-Kaan Agility Course");
		courses.add("Agility Pyramid");
		courses.add("Brimhaven Agility Arena");
		courses.add("Penguin Agility Course");
		courses.add("Hallowed Sepulchre");
		courses.add("Prifddinas Agility Course");
		courses.add("Colossal Wyrm Agility Course");
		courses.add("Shayzien Agility Course");
		courses.add("Shayzien Basic");
		courses.add("Shayzien Advanced");
		courses.add("Colossal Wyrm Basic");
		courses.add("Colossal Wyrm Advanced");
		courses.add("Skullball");
		KNOWN_COURSES = Collections.unmodifiableSet(courses);

		Map<String, String> aliases = new HashMap<>();
		aliases.put("Draynor Village Rooftop Course", "Draynor Village Rooftop");
		aliases.put("Al Kharid Rooftop Course", "Al Kharid Rooftop");
		aliases.put("Varrock Rooftop Course", "Varrock Rooftop");
		aliases.put("Canifis Rooftop Course", "Canifis Rooftop");
		aliases.put("Falador Rooftop Course", "Falador Rooftop");
		aliases.put("Seers' Village Rooftop Course", "Seers' Village Rooftop");
		aliases.put("Pollnivneach Rooftop Course", "Pollnivneach Rooftop");
		aliases.put("Rellekka Rooftop Course", "Rellekka Rooftop");
		aliases.put("Ardougne Rooftop Course", "Ardougne Rooftop");
		aliases.put("Gnome Stronghold Course", "Gnome Stronghold");
		aliases.put("Gnome Stronghold Agility", "Gnome Stronghold");
		aliases.put("Barbarian Outpost Course", "Barbarian Outpost");
		aliases.put("Barbarian Outpost Agility", "Barbarian Outpost");
		aliases.put("Ape Atoll Course", "Ape Atoll");
		aliases.put("Ape Atoll Agility", "Ape Atoll");
		aliases.put("Penguin Agility", "Penguin Agility Course");
		aliases.put("Werewolf Agility", "Werewolf Agility Course");
		aliases.put("Wilderness Agility", "Wilderness Agility Course");
		aliases.put("Dorgesh-Kaan Agility", "Dorgesh-Kaan Agility Course");
		aliases.put("Prifddinas Agility", "Prifddinas Agility Course");
		ALIASES = Collections.unmodifiableMap(aliases);

		Map<String, String> rooftops = new HashMap<>();
		rooftops.put("Draynor Village", "Draynor Village Rooftop");
		rooftops.put("Al Kharid", "Al Kharid Rooftop");
		rooftops.put("Varrock", "Varrock Rooftop");
		rooftops.put("Canifis", "Canifis Rooftop");
		rooftops.put("Falador", "Falador Rooftop");
		rooftops.put("Seers' Village", "Seers' Village Rooftop");
		rooftops.put("Pollnivneach", "Pollnivneach Rooftop");
		rooftops.put("Rellekka", "Rellekka Rooftop");
		rooftops.put("Ardougne", "Ardougne Rooftop");
		GRACE_ROOFTOP_NAMES = Collections.unmodifiableMap(rooftops);

		Set<String> skip = new HashSet<>();
		skip.add("Rooftop Agility");
		skip.add("Rooftop Agility Laps");
		skip.add("Miscellaneous Course");
		GRACE_HEADER_SKIP = Collections.unmodifiableSet(skip);
	}

	private AgilityCourses()
	{
	}

	static final class CourseLap
	{
		final String course;
		final int laps;

		CourseLap(String course, int laps)
		{
			this.course = course;
			this.laps = laps;
		}
	}

	static String normalizeCourseName(String name)
	{
		if (name == null)
		{
			return "";
		}

		String trimmed = name.trim();
		if (trimmed.endsWith(" Course"))
		{
			trimmed = trimmed.substring(0, trimmed.length() - " Course".length()).trim();
		}

		if (ALIASES.containsKey(trimmed))
		{
			return ALIASES.get(trimmed);
		}

		if (GRACE_ROOFTOP_NAMES.containsKey(trimmed))
		{
			return GRACE_ROOFTOP_NAMES.get(trimmed);
		}

		return trimmed;
	}

	static boolean isAgilityCourse(String name)
	{
		String normalized = normalizeCourseName(name);
		if (normalized.isEmpty())
		{
			return false;
		}
		if (normalized.endsWith(" Rooftop"))
		{
			return true;
		}
		return KNOWN_COURSES.contains(normalized);
	}

	static List<CourseLap> parseGraceLapScroll(String body)
	{
		if (body == null || body.isEmpty())
		{
			return new ArrayList<>();
		}

		String normalized = body.replace("<br>", "\n").replace('\u00A0', ' ').trim();
		List<CourseLap> entries = parseGraceEntries(normalized, GRACE_LAP_ENTRY_DASH);
		if (entries.isEmpty())
		{
			entries = parseGraceEntries(normalized, GRACE_LAP_ENTRY);
		}
		return entries;
	}

	private static List<CourseLap> parseGraceEntries(String body, Pattern pattern)
	{
		List<CourseLap> entries = new ArrayList<>();
		Matcher matcher = pattern.matcher(body);
		while (matcher.find())
		{
			String course = cleanGraceCourseRaw(matcher.group("course"));
			course = normalizeCourseName(course);
			if (course.isEmpty() || GRACE_HEADER_SKIP.contains(course))
			{
				continue;
			}

			int laps = Integer.parseInt(matcher.group("laps"));
			if (laps < 0)
			{
				continue;
			}

			entries.add(new CourseLap(course, laps));
		}
		return entries;
	}

	private static String cleanGraceCourseRaw(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		String cleaned = raw.trim();
		cleaned = cleaned.replaceFirst("^Miscellaneous Course:\\s*", "");

		cleaned = cleaned.replaceAll(".*Laps(?=[A-Z'])", "");
		cleaned = cleaned.replaceFirst("^Rooftop Agility Laps?", "").trim();

		return cleaned;
	}

	static OptionalInt parseGraceLapLine(String line)
	{
		List<CourseLap> entries = parseGraceLapScroll(line);
		if (entries.size() == 1)
		{
			return OptionalInt.of(entries.get(0).laps);
		}

		if (line == null || line.isEmpty())
		{
			return OptionalInt.empty();
		}

		Matcher matcher = GRACE_LAP_LINE_DASH.matcher(line.trim());
		if (!matcher.matches())
		{
			return OptionalInt.empty();
		}

		return OptionalInt.of(Integer.parseInt(matcher.group("laps")));
	}

	static String parseGraceCourseName(String line)
	{
		List<CourseLap> entries = parseGraceLapScroll(line);
		if (entries.size() == 1)
		{
			return entries.get(0).course;
		}

		if (line == null || line.isEmpty())
		{
			return "";
		}

		Matcher matcher = GRACE_LAP_LINE_DASH.matcher(line.trim());
		if (!matcher.matches())
		{
			return "";
		}

		return normalizeCourseName(matcher.group("course"));
	}
}

package is.flati.bosstracker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import is.flati.bosstracker.model.KcSyncPayload;
import is.flati.bosstracker.model.KcUpdatePayload;
import is.flati.bosstracker.model.KillPayload;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public class ApiClient
{
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final String USER_AGENT = "FlatiBossTracker/1.0";
	private static final String PLUGIN_DIR = "flati-boss-tracker";
	private static final String QUEUE_FILE = "queue.jsonl";

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final BossTrackerConfig config;
	private final ExecutorService queueExecutor;
	private Path queueDirectoryOverride;

	@Inject
	public ApiClient(OkHttpClient httpClient, Gson gson, BossTrackerConfig config)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.config = config;
		this.queueExecutor = Executors.newSingleThreadExecutor(queueThreadFactory());
	}

	public void shutdown()
	{
		httpClient.dispatcher().cancelAll();
		queueExecutor.shutdownNow();
	}

	public void sendKill(KillPayload payload)
	{
		enqueue(config.bossKillEndpoint(), payload, null);
	}

	public void sendKcUpdate(KcUpdatePayload payload)
	{
		enqueue(config.kcUpdateEndpoint(), payload, null);
	}

	public void sendKcSync(KcSyncPayload payload, Runnable onSuccess)
	{
		enqueue(config.kcSyncEndpoint(), payload, onSuccess);
	}

	public void flushRetryQueue()
	{
		queueExecutor.execute(this::drainRetryQueue);
	}

	void setQueueDirectoryForTesting(Path directory)
	{
		queueDirectoryOverride = directory;
	}

	void awaitQueueIdle() throws InterruptedException
	{
		try
		{
			queueExecutor.submit(() -> {}).get();
		}
		catch (ExecutionException e)
		{
			throw new IllegalStateException("Queue executor failed", e.getCause());
		}
	}

	private void enqueue(String url, Object payload, Runnable onSuccess)
	{
		if (!config.enableExternalSync())
		{
			return;
		}

		if (config.apiKey() == null || config.apiKey().isBlank())
		{
			log.debug("Flati Boss Tracker: API key not configured");
			return;
		}

		String body = gson.toJson(payload);
		postJsonAsync(url, body, onSuccess, true);
	}

	private void postJsonAsync(String url, String body, Runnable onSuccess, boolean queueOnFailure)
	{
		if (!config.enableExternalSync())
		{
			return;
		}

		if (config.apiKey() == null || config.apiKey().isBlank())
		{
			return;
		}

		Request request = buildRequest(url, body);

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Flati Boss Tracker: request error for {}", url, e);
				if (queueOnFailure)
				{
					scheduleQueuePayload(url, body);
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful())
					{
						log.warn("Flati Boss Tracker: request failed {} {}", res.code(), url);
						if (queueOnFailure && shouldRetainFailedRequest(res.code()))
						{
							scheduleQueuePayload(url, body);
						}
						return;
					}

					if (config.debugLogging())
					{
						log.debug("Flati Boss Tracker: sent to {}", url);
					}

					if (onSuccess != null)
					{
						onSuccess.run();
					}
				}
			}
		});
	}

	private void drainRetryQueue()
	{
		Path path = retryQueuePath();
		if (!Files.exists(path))
		{
			return;
		}

		List<String> lines;
		try
		{
			lines = Files.readAllLines(path, StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			log.warn("Flati Boss Tracker: failed to read retry queue", e);
			return;
		}

		List<String> remaining = new ArrayList<>();
		for (String line : lines)
		{
			if (line.isBlank())
			{
				continue;
			}

			QueuedRequest queued;
			try
			{
				queued = gson.fromJson(line, QueuedRequest.class);
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Flati Boss Tracker: dropping invalid queue entry", e);
				continue;
			}

			if (queued.url == null || queued.body == null)
			{
				log.warn("Flati Boss Tracker: dropping malformed queue entry");
				continue;
			}

			PostResult result = postJsonSync(queued.url, queued.body);
			if (result.success)
			{
				continue;
			}

			if (result.retainInQueue)
			{
				remaining.add(line);
			}
			else
			{
				log.warn("Flati Boss Tracker: dropping non-retryable queued request for {} ({})",
					queued.url, result.httpCode);
			}
		}

		writeQueueLines(path, remaining);
	}

	private PostResult postJsonSync(String url, String body)
	{
		if (!config.enableExternalSync() || config.apiKey() == null || config.apiKey().isBlank())
		{
			return PostResult.retain(0);
		}

		Request request = buildRequest(url, body);
		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.isSuccessful())
			{
				if (config.debugLogging())
				{
					log.debug("Flati Boss Tracker: replayed queued request to {}", url);
				}
				return PostResult.success();
			}

			log.warn("Flati Boss Tracker: queued request failed {} {}", response.code(), url);
			return shouldRetainFailedRequest(response.code())
				? PostResult.retain(response.code())
				: PostResult.drop(response.code());
		}
		catch (IOException e)
		{
			log.warn("Flati Boss Tracker: queued request error for {}", url, e);
			return PostResult.retain(0);
		}
	}

	private Request buildRequest(String url, String body)
	{
		return new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.header("Authorization", "Bearer " + config.apiKey())
			.post(RequestBody.create(JSON, body))
			.build();
	}

	static boolean shouldRetainFailedRequest(int httpCode)
	{
		if (httpCode == 0)
		{
			return true;
		}

		if (httpCode == 403 || httpCode == 429 || httpCode >= 500)
		{
			return true;
		}

		return false;
	}

	private void scheduleQueuePayload(String url, String body)
	{
		queueExecutor.execute(() -> appendQueuePayload(url, body));
	}

	private void appendQueuePayload(String url, String body)
	{
		try
		{
			Path path = retryQueuePath();
			Files.createDirectories(path.getParent());
			String line = gson.toJson(new QueuedRequest(url, body)) + System.lineSeparator();
			Files.writeString(path, line, StandardCharsets.UTF_8,
				java.nio.file.StandardOpenOption.CREATE,
				java.nio.file.StandardOpenOption.APPEND);
		}
		catch (IOException e)
		{
			log.warn("Flati Boss Tracker: failed to queue payload", e);
		}
	}

	private void writeQueueLines(Path path, List<String> remaining)
	{
		try
		{
			if (remaining.isEmpty())
			{
				Files.deleteIfExists(path);
				return;
			}

			Files.createDirectories(path.getParent());
			Files.write(path, remaining, StandardCharsets.UTF_8);
		}
		catch (IOException e)
		{
			log.warn("Flati Boss Tracker: failed to update retry queue", e);
		}
	}

	private Path retryQueuePath()
	{
		Path base = queueDirectoryOverride != null
			? queueDirectoryOverride
			: RuneLite.RUNELITE_DIR.toPath().resolve(PLUGIN_DIR);
		return base.resolve(QUEUE_FILE);
	}

	private static ThreadFactory queueThreadFactory()
	{
		return runnable -> {
			Thread thread = new Thread(runnable, "flati-boss-tracker-queue");
			thread.setDaemon(true);
			return thread;
		};
	}

	private static final class PostResult
	{
		private final boolean success;
		private final boolean retainInQueue;
		private final int httpCode;

		private PostResult(boolean success, boolean retainInQueue, int httpCode)
		{
			this.success = success;
			this.retainInQueue = retainInQueue;
			this.httpCode = httpCode;
		}

		private static PostResult success()
		{
			return new PostResult(true, false, 0);
		}

		private static PostResult retain(int httpCode)
		{
			return new PostResult(false, true, httpCode);
		}

		private static PostResult drop(int httpCode)
		{
			return new PostResult(false, false, httpCode);
		}
	}

	private static class QueuedRequest
	{
		private String url;
		private String body;

		@SuppressWarnings("unused")
		private QueuedRequest()
		{
		}

		private QueuedRequest(String url, String body)
		{
			this.url = url;
			this.body = body;
		}
	}
}

package is.flati.bosstracker;

import is.flati.bosstracker.model.KcSyncPayload;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Slf4j
@Singleton
public class BossLogSync
{
	private final Client client;
	private final BossTrackerConfig config;
	private final ApiClient apiClient;

	private boolean bossLogLoaded;

	@Inject
	public BossLogSync(Client client, BossTrackerConfig config, ApiClient apiClient)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
	}

	public void markBossLogLoaded()
	{
		bossLogLoaded = true;
	}

	public void onGameTick()
	{
		if (!config.enableExternalSync() || !bossLogLoaded)
		{
			return;
		}
		bossLogLoaded = false;
		syncFromOpenBossLog(null);
	}

	public boolean syncFromOpenBossLog(Runnable onSuccess)
	{
		Widget title = client.getWidget(InterfaceID.KillLog.INTERFACE_TITLE);
		Widget bossMonster = client.getWidget(InterfaceID.KillLog.NAME);
		Widget bossKills = client.getWidget(InterfaceID.KillLog.KILL);

		if (title == null || bossMonster == null || bossKills == null
			|| !"Boss Kill Log".equals(title.getText()))
		{
			return false;
		}

		Widget[] bossChildren = bossMonster.getChildren();
		Widget[] killsChildren = bossKills.getChildren();
		if (bossChildren == null || killsChildren == null)
		{
			return false;
		}

		List<KcSyncPayload.KcEntry> entries = new ArrayList<>();
		for (int i = 0; i < bossChildren.length && i < killsChildren.length; i++)
		{
			Widget boss = bossChildren[i];
			Widget kill = killsChildren[i];
			if (boss == null || kill == null)
			{
				continue;
			}

			String bossName = BossRegistry.normalizeBossName(boss.getText());
			int kc;
			try
			{
				kc = Integer.parseInt(kill.getText().replace(",", ""));
			}
			catch (NumberFormatException e)
			{
				continue;
			}

			if (kc <= 0 || bossName.isEmpty())
			{
				continue;
			}

			entries.add(KcSyncPayload.KcEntry.builder()
				.bossName(bossName)
				.killCount(kc)
				.build());
		}

		if (entries.isEmpty())
		{
			return false;
		}

		String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		if (playerName == null)
		{
			return false;
		}

		KcSyncPayload payload = KcSyncPayload.builder()
			.playerName(playerName)
			.source("boss_log")
			.updatedAt(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString())
			.entries(entries)
			.build();

		apiClient.sendKcSync(payload, onSuccess);

		if (config.debugLogging())
		{
			log.debug("Boss log sync: {} entries", entries.size());
		}

		return true;
	}
}

