		else if (event.getGroupId() == InterfaceID.LONGSCROLL)
		{
			if (config.debugLogging())
			{
				log.debug("WidgetLoaded: LONGSCROLL ({})", InterfaceID.LONGSCROLL);
			}
			graceLapSync.markGraceLapsLoaded();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			collectionLogSync.markCollectionLogDrawn();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		killCountParser.onChatMessage(event);
	}
}

package is.flati.bosstracker;

/**
 * Chat colour wrappers used in game messages.
 * Numbers may be wrapped in {@code <col=rrggbb>} or in the newer {@code @macro@…</col>} form.
 */
final class ChatMarkup
{
	static final String COLOR_OPEN = "(?:<col=[0-9a-f]{6}>|@.+?@)?";
	static final String COLOR_CLOSE = "(?:</col>)?";

	private ChatMarkup()
	{
	}

	static String coloredDigits(String groupName)
	{
		return COLOR_OPEN + "(?<" + groupName + ">\\d+)" + COLOR_CLOSE;
	}

	static String coloredCount(String groupName)
	{
		return COLOR_OPEN + "(?<" + groupName + ">[0-9,]+)" + COLOR_CLOSE;
	}
}

package is.flati.bosstracker;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class ClueChatParser
{
	static final class ClueCompletion
	{
		private final String bossName;
		private final int count;

		ClueCompletion(String bossName, int count)
		{
			this.bossName = bossName;
			this.count = count;
		}

		String getBossName()
		{
			return bossName;
		}

		int getCount()
		{
			return count;
		}
	}

	private static final Map<String, String> TIER_TO_BOSS_NAME = new HashMap<>();

	static
	{
		TIER_TO_BOSS_NAME.put("beginner", "Beginner clues completed");
		TIER_TO_BOSS_NAME.put("easy", "Easy clues completed");
		TIER_TO_BOSS_NAME.put("medium", "Medium clues completed");
		TIER_TO_BOSS_NAME.put("hard", "Hard clues completed");
		TIER_TO_BOSS_NAME.put("elite", "Elite clues completed");
		TIER_TO_BOSS_NAME.put("master", "Master clues completed");
	}

	static final Pattern COMPLETION_PATTERN = Pattern.compile(
		"You have completed " + ChatMarkup.coloredCount("count")
			+ " (?<tier>beginner|easy|medium|hard|elite|master) Treasure Trails?\\.",
		Pattern.CASE_INSENSITIVE);

	private ClueChatParser()
	{
	}

	static Optional<ClueCompletion> parse(String message)
	{
		if (message == null || message.isEmpty())
		{
			return Optional.empty();
		}

		Matcher matcher = COMPLETION_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return Optional.empty();
		}

		String tier = matcher.group("tier").toLowerCase();
		String bossName = TIER_TO_BOSS_NAME.get(tier);
		if (bossName == null)
		{
			return Optional.empty();
		}

		int count = Integer.parseInt(matcher.group("count").replace(",", ""));
		return Optional.of(new ClueCompletion(bossName, count));
	}
}

package is.flati.bosstracker;

import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class CollectionLogSync
{
	private final Client client;
	private final BossTrackerConfig config;
	private final KillCountParser killCountParser;

	private boolean collectionLogDrawn;

	@Inject
	public CollectionLogSync(Client client, BossTrackerConfig config, KillCountParser killCountParser)
	{
		this.client = client;
		this.config = config;
		this.killCountParser = killCountParser;
	}

	public void markCollectionLogDrawn()
	{
		collectionLogDrawn = true;
	}

	public void onGameTick()
	{
		if (!collectionLogDrawn)
		{
			return;
		}
		collectionLogDrawn = false;

		if (config.debugLogging())
		{
			log.debug("Collection log page drawn, syncing KC");
		}

		syncCurrentPage();
	}

	public void syncCurrentPage()
	{
		if (!config.enableExternalSync() || !config.syncKcFromCollectionLog())
		{
			return;
		}

		Widget pageHead = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		if (pageHead == null || pageHead.getDynamicChildren() == null)
		{
			return;
		}

		Widget[] children = pageHead.getDynamicChildren();
		if (children.length < 3)
		{
			return;
		}

		Widget[] killCountWidgets = Arrays.copyOfRange(children, 2, children.length);
		for (Widget killCountWidget : killCountWidgets)
		{
			if (killCountWidget == null)
			{
				continue;
			}

			String killCountString = Text.removeTags(killCountWidget.getText());
			if (killCountString == null || !killCountString.contains(": "))
			{
				continue;
			}

			String[] parts = killCountString.split(": ", 2);
			if (parts.length != 2)
			{
				continue;
			}

			String label = BossRegistry.normalizeBossName(parts[0]);
			int amount;
			try
			{
				amount = Integer.parseInt(parts[1].replace(",", ""));
			}
			catch (NumberFormatException e)
			{
				continue;
			}

			String bossName = label;
			if ("Kill count".equalsIgnoreCase(label) && children[0] != null)
			{
				bossName = BossRegistry.normalizeBossName(Text.removeTags(children[0].getText()));
			}

			if (bossName.isEmpty() || amount < 0)
			{
				continue;
			}

			killCountParser.sendKcUpdate(bossName, amount);

			if (config.debugLogging())
			{
				log.debug("Collection log KC: {} = {}", bossName, amount);
			}
		}
	}
}

package is.flati.bosstracker;

import java.util.OptionalInt;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class DelveChatParser
{
	static final String BOSS_NAME = "Delve";
	static final String DEEPEST_DELVE = "Deepest delve";
	static final String DEEP_DELVES = "Deep delves";
	static final String TOTAL_DELVES = "Total delves";

	// Levels past 8 are "8+ (9)". colouredDigits already wraps each number (open + digits + close).
	// The extra COLOR_CLOSE after ")" consumes a tag that wrapped the whole "8+ (9)", whose
	// COLOR_OPEN was taken by the floor group: <col=ff0000>8+ (9)</col>
	static final Pattern FLOOR_PATTERN = Pattern.compile(
		"Delve level: " + ChatMarkup.coloredDigits("floor")
			+ "(?:" + ChatMarkup.COLOR_OPEN + "\\+ \\(" + ChatMarkup.coloredDigits("deepFloor") + "\\)"
			+ ChatMarkup.COLOR_CLOSE + ")?"
			+ " duration: " + ChatMarkup.COLOR_OPEN + "(?<duration>\\d+:\\d{2})" + ChatMarkup.COLOR_CLOSE);

	static final Pattern DEEP_DELVES_PATTERN = Pattern.compile(
		"Deep delves completed: " + ChatMarkup.coloredDigits("kc"));

	private DelveChatParser()
	{
	}

	static OptionalInt parseFloor(String message)
	{
		if (message == null || message.isEmpty())
		{
			return OptionalInt.empty();
		}

		Matcher matcher = FLOOR_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return OptionalInt.empty();
		}

		String deepFloor = matcher.group("deepFloor");
		return OptionalInt.of(Integer.parseInt(deepFloor != null ? deepFloor : matcher.group("floor")));
	}

	static OptionalInt parseDeepDelvesCompleted(String message)
	{
		if (message == null || message.isEmpty())
		{
			return OptionalInt.empty();
		}

		Matcher matcher = DEEP_DELVES_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return OptionalInt.empty();
		}

		return OptionalInt.of(Integer.parseInt(matcher.group("kc")));
	}
}

package is.flati.bosstracker;

import is.flati.bosstracker.model.KcSyncPayload;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class GraceLapSync
{
	private static final int GRACE_SYNC_RETRY_TICKS = 5;

	private final Client client;
	private final BossTrackerConfig config;
	private final ApiClient apiClient;

	private int graceLapsRetryTicks;

	@Inject
	public GraceLapSync(Client client, BossTrackerConfig config, ApiClient apiClient)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
	}

	public void markGraceLapsLoaded()
	{
		graceLapsRetryTicks = GRACE_SYNC_RETRY_TICKS;
		debug("Longscroll widget loaded; will attempt Grace lap sync for up to {} ticks", GRACE_SYNC_RETRY_TICKS);
	}

	public void onGameTick()
	{
		if (!config.enableExternalSync() || !config.syncKcFromGraceLaps())
		{
			return;
		}

		if (graceLapsRetryTicks <= 0)
		{
			return;
		}

		if (syncFromGraceLaps(null))
		{
			graceLapsRetryTicks = 0;
			return;
		}

		graceLapsRetryTicks--;
		debug("Grace lap sync attempt failed; {} tick(s) remaining", graceLapsRetryTicks);
	}

	public boolean syncFromGraceLaps(Runnable onSuccess)
	{
		debug("Grace lap sync: reading Longscroll widgets");

		Widget title = client.getWidget(InterfaceID.Longscroll.SCROLL_TITLE);
		Widget textWidget = client.getWidget(InterfaceID.Longscroll.SCROLL_TEXT);
		Widget textLayer = client.getWidget(InterfaceID.Longscroll.SCROLL_TEXT_LAYER);

		debug("Widgets title={} text={} textLayer={}",
			widgetSummary(title), widgetSummary(textWidget), widgetSummary(textLayer));

		if (title == null)
		{
			debug("Grace lap sync: SCROLL_TITLE widget is null");
			return false;
		}

		String headerText = Text.removeTags(title.getText());
		debug("Grace lap sync: header text={}", headerText);

		if (!isGraceLapHeader(headerText))
		{
			debug("Grace lap sync: header does not match Grace lap scroll");
			return false;
		}

		String body = collectScrollText(textWidget, textLayer);
		if (body.isEmpty())
		{
			debug("Grace lap sync: scroll body is empty");
			return false;
		}

		debug("Grace lap sync: scroll body ({} chars): {}", body.length(), truncate(body, 500));

		List<KcSyncPayload.KcEntry> entries = new ArrayList<>();
		for (AgilityCourses.CourseLap courseLap : AgilityCourses.parseGraceLapScroll(body))
		{
			debug("Grace lap sync: parsed {} = {}", courseLap.course, courseLap.laps);
			entries.add(KcSyncPayload.KcEntry.builder()
				.bossName(courseLap.course)
				.killCount(courseLap.laps)
				.build());
		}

		if (entries.isEmpty())
		{
			debug("Grace lap sync: no lap entries parsed from scroll body");
			return false;
		}

		String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		if (playerName == null)
		{
			debug("Grace lap sync: local player name unavailable");
			return false;
		}

		KcSyncPayload payload = KcSyncPayload.builder()
			.playerName(playerName)
			.source("grace_laps")
			.updatedAt(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString())
			.entries(entries)
			.build();

		apiClient.sendKcSync(payload, onSuccess);
		log.info("Grace lap sync: queued {} courses for {}", entries.size(), playerName);
		debug("Grace lap sync: kc-sync payload sent with {} entries", entries.size());

		return true;
	}

	private static boolean isGraceLapHeader(String headerText)
	{
		if (headerText == null || headerText.isEmpty())
		{
			return false;
		}

		String trimmed = headerText.trim();
		return AgilityCourses.GRACE_LAPS_HEADER.equals(trimmed)
			|| trimmed.contains("Agility Course Lap Counts");
	}

	private static String collectScrollText(Widget textWidget, Widget textLayer)
	{
		StringBuilder builder = new StringBuilder();
		appendWidgetText(textWidget, builder);
		appendWidgetText(textLayer, builder);

		if (textLayer != null && textLayer.getChildren() != null)
		{
			for (Widget child : textLayer.getChildren())
			{
				appendWidgetText(child, builder);
			}
		}

		return builder.toString().trim();
	}

	private static void appendWidgetText(Widget widget, StringBuilder builder)
	{
		if (widget == null)
		{
			return;
		}

		String text = Text.removeTags(widget.getText());
		if (text == null || text.isEmpty())
		{
			return;
		}

		if (builder.length() > 0)
		{
			builder.append('\n');
		}
		builder.append(text.trim());
	}

	private static String widgetSummary(Widget widget)
	{
		if (widget == null)
		{
			return "null";
		}

		String text = Text.removeTags(widget.getText());
		if (text == null || text.isEmpty())
		{
			return "empty";
		}

		return truncate(text, 80);
	}

	private static String truncate(String value, int maxLen)
	{
		if (value.length() <= maxLen)
		{
			return value;
		}
		return value.substring(0, maxLen) + "...";
	}

	private void debug(String format, Object... args)
	{
		if (config.debugLogging())
		{
			log.debug(format, args);
		}
	}
}

package is.flati.bosstracker;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class HunterRumourChatParser
{
	static final String BOSS_NAME = "Hunter rumours";

	static final class RumourCompletion
	{
		private final int count;

		RumourCompletion(int count)
		{
			this.count = count;
		}

		int getCount()
		{
			return count;
		}
	}

	static final Pattern COMPLETION_PATTERN = Pattern.compile(
		"You have completed " + ChatMarkup.coloredCount("count")
			+ " rumours for the Hunter Guild\\.",
		Pattern.CASE_INSENSITIVE);

	private HunterRumourChatParser()
	{
	}

	static Optional<RumourCompletion> parse(String message)
	{
		if (message == null || message.isEmpty())
		{
			return Optional.empty();
		}

		Matcher matcher = COMPLETION_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return Optional.empty();
		}

		int count = Integer.parseInt(matcher.group("count").replace(",", ""));
		return Optional.of(new RumourCompletion(count));
	}
}

package is.flati.bosstracker;

import is.flati.bosstracker.model.KcUpdatePayload;
import is.flati.bosstracker.model.KillPayload;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;

@Slf4j
@Singleton
public class KillCountParser
{
	static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?" + ChatMarkup.COLOR_OPEN + "(?<boss>.+?)"
			+ ChatMarkup.COLOR_CLOSE + " "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ ChatMarkup.coloredCount("kc"));

	private final Client client;
	private final BossTrackerConfig config;
	private final ApiClient apiClient;
	private final KillEventSender killEventSender;

	@Inject
	public KillCountParser(Client client, BossTrackerConfig config, ApiClient apiClient,
		KillEventSender killEventSender)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.killEventSender = killEventSender;
	}

	public void onChatMessage(ChatMessage chatMessage)
	{
		if (!config.enableExternalSync() || !config.syncKcFromChat())
		{
			return;
		}

		ChatMessageType type = chatMessage.getType();
		if (type != ChatMessageType.GAMEMESSAGE
			&& type != ChatMessageType.SPAM
			&& type != ChatMessageType.TRADE
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}

		String message = chatMessage.getMessage();
		String killedAt = Instant.now().truncatedTo(ChronoUnit.SECONDS).toString();

		if (handleDelveMessage(message, killedAt))
		{
			return;
		}

		if (handleSepulchreMessage(message, killedAt))
		{
			return;
		}

		if (handleHunterRumourMessage(message, killedAt))
		{
			return;
		}

		if (handleClueMessage(message, killedAt))
		{
			return;
		}

		Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String pre = matcher.group("pre");
		String post = matcher.group("post");
		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return;
		}

		String boss = BossRegistry.normalizeBossName(matcher.group("boss"));
		if (post != null && post.contains("lap"))
		{
			boss = AgilityCourses.normalizeCourseName(boss);
		}
		int kc = Integer.parseInt(matcher.group("kc").replace(",", ""));

		sendKcUpdate(boss, kc, killedAt);
		killEventSender.sendKill(boss, kc, killedAt);
	}

	private boolean handleDelveMessage(String message, String killedAt)
	{
		java.util.OptionalInt floor = DelveChatParser.parseFloor(message);
		if (floor.isPresent())
		{
			int floorNumber = floor.getAsInt();
			if (floorNumber > 0)
			{
				killEventSender.sendKill(DelveChatParser.BOSS_NAME, floorNumber, killedAt);
				sendKcUpdate(DelveChatParser.DEEPEST_DELVE, floorNumber, killedAt);

				if (config.debugLogging())
				{
					log.debug("Delve floor cleared: {}", floorNumber);
				}
			}
			return true;
		}

		java.util.OptionalInt deepDelves = DelveChatParser.parseDeepDelvesCompleted(message);
		if (deepDelves.isPresent())
		{
			sendKcUpdate(DelveChatParser.DEEP_DELVES, deepDelves.getAsInt(), killedAt);

			if (config.debugLogging())
			{
				log.debug("Deep delves completed: {}", deepDelves.getAsInt());
			}
			return true;
		}

		return false;
	}

	private boolean handleSepulchreMessage(String message, String killedAt)
	{
		java.util.OptionalInt coffinsOpened = SepulchreChatParser.parseCoffinsOpened(message);
		if (coffinsOpened.isPresent())
		{
			int totalCoffins = coffinsOpened.getAsInt();
			killEventSender.sendKill(
				SepulchreChatParser.COFFIN_BOSS_NAME, totalCoffins, killedAt);
			sendKcUpdate(SepulchreChatParser.COFFINS_OPENED, totalCoffins, killedAt);

			if (config.debugLogging())
			{
				log.debug("Grand Hallowed Coffin opened: {}", totalCoffins);
			}
			return true;
		}

		java.util.OptionalInt floor = SepulchreChatParser.parseFloorCompletion(message);
		if (floor.isPresent())
		{
			int floorNumber = floor.getAsInt();
			killEventSender.sendKill(SepulchreChatParser.TIMELINE_BOSS_NAME, floorNumber, killedAt);

			if (config.debugLogging())
			{
				log.debug("Hallowed Sepulchre floor completed: {}", floorNumber);
			}
			return true;
		}

		return false;
	}

	private boolean handleHunterRumourMessage(String message, String killedAt)
	{
		java.util.Optional<HunterRumourChatParser.RumourCompletion> completion =
			HunterRumourChatParser.parse(message);
		if (!completion.isPresent())
		{
			return false;
		}

		int count = completion.get().getCount();
		sendKcUpdate(HunterRumourChatParser.BOSS_NAME, count, killedAt);
		killEventSender.sendKill(HunterRumourChatParser.BOSS_NAME, count, killedAt);

		if (config.debugLogging())
		{
			log.debug("Hunter rumour completed: {} = {}", HunterRumourChatParser.BOSS_NAME, count);
		}

		return true;
	}

	private boolean handleClueMessage(String message, String killedAt)
	{
		java.util.Optional<ClueChatParser.ClueCompletion> completion = ClueChatParser.parse(message);
		if (!completion.isPresent())
		{
			return false;
		}

		ClueChatParser.ClueCompletion clue = completion.get();
		sendKcUpdate(clue.getBossName(), clue.getCount(), killedAt);

		if (config.debugLogging())
		{
			log.debug("Clue completed: {} = {}", clue.getBossName(), clue.getCount());
		}

		return true;
	}

	public void sendKcUpdate(String bossName, int killCount)
	{
		sendKcUpdate(bossName, killCount, Instant.now().truncatedTo(ChronoUnit.SECONDS).toString());
	}

	private void sendKcUpdate(String bossName, int killCount, String updatedAt)
	{
		String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		if (playerName == null)
		{
			return;
		}

		KcUpdatePayload payload = KcUpdatePayload.builder()
			.playerName(playerName)
			.bossName(bossName)
			.killCount(killCount)
			.updatedAt(updatedAt)
			.build();

		apiClient.sendKcUpdate(payload);

		if (config.debugLogging())
		{
			log.debug("KC update: {} = {}", bossName, killCount);
		}
	}
}

