	{
		OptionalInt floor = DelveChatParser.parseFloor(
			"Delve level: 7 duration: @mes_hl_red@1:35</col>. Personal best: @mes_hl_red@1:22</col>");
		assertTrue(floor.isPresent());
		assertEquals(7, floor.getAsInt());
